// 1) جلب جميع الأوردرات الخاصة بهذا العميل القادمة من نود Get Orders
const allCustomerOrders = $input.all();

if (!allCustomerOrders || allCustomerOrders.length === 0) {
  return [{
    json: {
      can_track: false,
      reply_message: "عذراً، لم نجد أي أوردرات سابقة مسجلة برقمك حالياً."
    }
  }];
}

// 2) اختيار أحدث أوردر (آخر عنصر في القائمة التي رجعت من الجوجل شيت)
const latestOrderRow = allCustomerOrders[allCustomerOrders.length - 1].json;

// 3) قراءة الحقول بأمان مع مراعاة كافة مسميات الأعمدة المتوقعة في Google Sheets
const orderId = latestOrderRow.order_id || latestOrderRow["Order_ID"] || latestOrderRow["Order ID"] || "غير محدد";
const orderTimeRaw = latestOrderRow.date_time || latestOrderRow["Date Time"] || latestOrderRow["Date_Time"] || latestOrderRow["date"] || latestOrderRow.created_at;
const orderStatus = latestOrderRow.order_status || latestOrderRow["Order_Status"] || latestOrderRow["Order Status"] || "قيد التحضير";
const orderedItems = latestOrderRow.ordered_items || latestOrderRow["Ordered_Items"] || latestOrderRow["Ordered Items"] || "الطلب الخاص بك";

const chatId = latestOrderRow.chat_id || latestOrderRow["Chat_ID"] || latestOrderRow["Chat ID"] || $('Prepare Input').item.json.chat_id || "";
const customerName = latestOrderRow.customer_name || latestOrderRow["Customer_Name"] || latestOrderRow["Customer Name"] || latestOrderRow["Name"] || "عميلنا العزيز";
const phoneNumber = latestOrderRow.phone_number || latestOrderRow["Phone_Number"] || latestOrderRow["Phone Number"] || latestOrderRow["Phone"] || "غير محدد";
const deliveryAddress = latestOrderRow.delivery_address || latestOrderRow["Delivery_Address"] || latestOrderRow["Delivery Address"] || latestOrderRow["Address"] || "غير محدد";

// 4) حساب فرق الوقت بالدقائق
const now = new Date();
let orderDate = new Date(orderTimeRaw);

// في حالة عدم إمكانية تفكيك التاريخ، نفترض مرور 20 دقيقة للسماح بالتتبع
if (isNaN(orderDate.getTime())) {
  orderDate = new Date(now.getTime() - 20 * 60 * 1000);
}

const diffInMinutes = Math.floor((now - orderDate) / (1000 * 60));
const minWaitTime = 15; // الحد الأدنى لطلب التتبع (15 دقيقة)

// 5) التوجيه بناءً على الوقت المنقضي
if (diffInMinutes < minWaitTime) {
  const remainingTime = minWaitTime - diffInMinutes;

  const falseMessage = 
`👨‍🍳 **أوردرك جاري تحضيره بكل حب في المطبخ!**

📌 **رقم الأوردر:** ${orderId}
📊 **الحالة الحالية:** ${orderStatus}
⏱️ **الوقت المنقضي:** ${diffInMinutes} دقيقة فقط

💡 **ملاحظة:** يتم تجهيز وتغليف الوجبات طازجة فور طلبها. يستغرق التحضير المبدئي حوالي **15 دقيقة** قبل خروج الطيار.

يمكنك إعادة التتبع والتواصل مع المطبخ بعد **${remainingTime} دقائق** للتأكد من خط السير! 🛵

نشكر صبرك ونعدك بأكلة تشرفك! ❤️`;

  return [{
    json: {
      can_track: false,
      diff_minutes: diffInMinutes,
      order_id: orderId,
      chat_id: chatId,
      customer_name: customerName,
      phone_number: phoneNumber,
      delivery_address: deliveryAddress,
      reply_message: falseMessage
    }
  }];

} else {
  const trueCustomerMessage = 
`🔍 **جاري تتبع طلبك الآن...**

📌 **رقم الأوردر:** ${orderId}
📋 **تفاصيل الطلب:** ${orderedItems}
⏱️ **الوقت المنقضي:** ${diffInMinutes} دقيقة

تم إرسال تنبيه عاجل لفرع المطعم للتحقق من موقع طيار التوصيل. سنوافيك بالتحديث فوراً خلال لحظات! 🛵✨`;

  return [{
    json: {
      can_track: true,
      diff_minutes: diffInMinutes,
      order_id: orderId,
      chat_id: chatId,
      customer_name: customerName,
      phone_number: phoneNumber,
      delivery_address: deliveryAddress,
      ordered_items: orderedItems,
      order_status: orderStatus,
      reply_message: trueCustomerMessage
    }
  }];
}

const rows = $input.all().map(i => i.json);
const chatId = String($('Prepare Input').item.json.chat_id);
const mine = rows.filter(r => String(r.Chat_ID) === chatId);
const original = $('Prepare Input').item.json;

if (mine.length === 0) {
  return [{ json: { ...original, message: { ...original.message, text: "معنديش أوردر سابق مسجل باسمك، تحب تبدأ أوردر جديد؟ 😊" } } }];
}
const last = mine[mine.length - 1];
return [{ json: { ...original, message: { ...original.message,
  text: `عايز أطلب زي أوردري اللي فات بالظبط: ${last.Ordered_Items}. من فضلك أكدّي التفاصيل والسعر.`
} } }];

var callbackData = "";
try {
  callbackData = $input.first().json.callback_query.data;
} catch (error) {
  callbackData = "";
}
if (!callbackData) {
  try {
    callbackData = $("Callback Trigger").item.json.callback_query.data;
  } catch (error) {
    callbackData = "";
  }
}

var parts = String(callbackData || "").split("|");
var action = parts[0] || "";
var orderId = parts[1] || "";
var customerChatId = parts[2] || "";

if (action === "payment") {
  return [{
    json: {
      action: "payment",
      order_id: orderId,
      customer_chat_id: customerChatId,
      new_payment_status: parts[3] || "paid",
      customer_message: "تم تأكيد استلام الدفع النقدي للطلب رقم " + orderId + " بنجاح. شكرًا لك ❤️"
    }
  }];
}

if (action !== "status") {
  return [];
}

var statusCode = parts[3] || "preparing";
var statusLabels = {
  pending: "قيد الانتظار",
  preparing: "قيد التحضير",
  out_for_delivery: "خرج للتوصيل",
  completed: "تم التسليم",
  cancelled: "تم إلغاء الطلب"
};
var statusLabel = statusLabels[statusCode] || statusCode;

return [{
  json: {
    action: "status",
    order_id: orderId,
    customer_chat_id: customerChatId,
    new_status: statusCode,
    customer_message: "🔔 تحديث جديد بخصوص طلبك رقم #" + orderId + ":\nحالة الأوردر الآن: " + statusLabel + " 🚀"
  }
}];

function getValue(obj, key, fallback) {
  if (
    obj &&
    obj[key] !== undefined &&
    obj[key] !== null &&
    obj[key] !== ""
  ) {
    return obj[key];
  }

  return fallback;
}

// 1. Read AI Agent output
var rawText = "";

try {
  var aiData = $("AI Agent").first().json;

  if (typeof aiData === "string") {
    rawText = aiData;
  } else {
    rawText = getValue(aiData, "output", "");

    if (!rawText) {
      rawText = getValue(aiData, "text", "");
    }

    if (!rawText) {
      rawText = getValue(aiData, "message", "");
    }

    if (!rawText) {
      rawText = JSON.stringify(aiData);
    }
  }
} catch (error) {
  var inputData = $input.first().json;

  rawText = getValue(inputData, "output", "");

  if (!rawText) {
    rawText = getValue(inputData, "text", "");
  }

  if (!rawText) {
    rawText = getValue(inputData, "message", "");
  }
}

rawText = String(rawText || "").trim();

// 2. Parse AI response JSON
var parsed = null;

try {
  var cleaned = rawText
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim()
    .replace(/^json\s*/i, "");

  var firstBrace = cleaned.indexOf("{");
  var lastBrace = cleaned.lastIndexOf("}");

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }

  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = null;
}

// 3. Initialize order data
var isOrder = false;
var customerName = "غير محدد";
var phoneNumber = "غير محدد";
var deliveryAddress = "غير محدد";
var orderedItems = "غير محدد";
var subtotalPrice = 0;
var paymentMethod = "كاش";
var replyMessage = rawText;

if (parsed && typeof parsed === "object") {
  isOrder = parsed.is_order === true;

  replyMessage = String(
    getValue(parsed, "reply_message", "")
  );

  if (isOrder) {
    customerName = getValue(
      parsed,
      "customer_name",
      customerName
    );

    phoneNumber = getValue(
      parsed,
      "phone_number",
      phoneNumber
    );

    deliveryAddress = getValue(
      parsed,
      "delivery_address",
      deliveryAddress
    );

    orderedItems = getValue(
      parsed,
      "ordered_items",
      orderedItems
    );

    paymentMethod = getValue(
      parsed,
      "payment_method",
      paymentMethod
    );

    var priceValue = Number(parsed.total_price);

    if (isFinite(priceValue) && priceValue >= 0) {
      subtotalPrice = priceValue;
    }
  }
}

// 4. Clean reply message
replyMessage = String(replyMessage)
  .replace(/\\n/g, "\n")
  .replace(/\\"/g, '"')
  .trim();

// 5. Return normal AI replies without creating an order
if (!isOrder) {
  return [
    {
      json: {
        is_order: false,
        reply_message: replyMessage
      }
    }
  ];
}

// 6. Read Chat ID
var chatId = "";

try {
  chatId = getValue(
    $("Prepare Input").first().json,
    "chat_id",
    ""
  );
} catch (error) {
  chatId = getValue(
    $input.first().json,
    "chat_id",
    ""
  );
}

// 7. Generate order number
var nextOrderNumber = 1;

try {
  var allOrders = $("Get Last Order").all();

  if (allOrders.length > 0) {
    var lastRow = allOrders[allOrders.length - 1].json;

    var lastOrderId = getValue(
      lastRow,
      "order_id",
      ""
    );

    if (!lastOrderId) {
      lastOrderId = getValue(
        lastRow,
        "Order_ID",
        ""
      );
    }

    if (!lastOrderId) {
      lastOrderId = getValue(
        lastRow,
        "Order ID",
        ""
      );
    }

    var match = String(lastOrderId).match(/(\d+)$/);

    if (match) {
      nextOrderNumber = parseInt(match[1], 10) + 1;
    } else {
      nextOrderNumber = allOrders.length + 1;
    }
  }
} catch (error) {
  nextOrderNumber = 1;
}

var orderId = "ONL-" + nextOrderNumber;

// 8. Calculate prices
var deliveryFee = 35;
var grandTotal = subtotalPrice + deliveryFee;

// 9. Date and time
var dateTime = new Date().toLocaleString("en-GB", {
  timeZone: "Africa/Cairo"
});

// 10. Payment status
// All new orders start unpaid.
// Payment confirmation must happen in a separate workflow.
var paymentStatus = "pending";

// 11. Initial order status
var orderStatus = "pending";

// 12. Build customer confirmation message
var messageLines = [
  "🎉 تم تأكيد طلبك بنجاح من مطعم كوركيت 🥩",
  "",
  "رقم الأوردر: " + orderId,
  "----------------------------------------",
  "📋 تفاصيل الطلب:",
  String(orderedItems),
  "",
  "👤 الاسم: " + customerName,
  "📞 رقم التواصل: " + phoneNumber,
  "📍 عنوان التوصيل: " + deliveryAddress,
  "💳 طريقة الدفع: " + paymentMethod,
  "----------------------------------------",
  "💵 سعر الأصناف: " + subtotalPrice + " ج.م",
  "🚚 التوصيل: " + deliveryFee + " ج.م",
  "💰 الإجمالي النهائي: " + grandTotal + " ج.م",
  "",
  "شكراً لاختيارك كوركيت وبالهناء والشفاء! ❤️"
];

var finalOrderMessage = messageLines.join("\n");

// 13. Return complete order data
return [
  {
    json: {
      is_order: true,
      order_type: "Online Order",
      order_id: orderId,
      date_time: dateTime,
      chat_id: chatId,
      customer_name: customerName,
      phone_number: phoneNumber,
      delivery_address: deliveryAddress,
      ordered_items: orderedItems,
      subtotal: subtotalPrice,
      delivery_fee: deliveryFee,
      grand_total: grandTotal,
      payment_method: paymentMethod,
      payment_status: paymentStatus,
      order_status: orderStatus,
      reply_message: finalOrderMessage
    }
  }
];

